package com.oms.order.service;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class OrderAllocationPolicyTest {
    Map<String,Object> store(String code,String owner){Map<String,Object> s=new HashMap<>();s.put("wms_simulation_code",code);s.put("owner_code",owner);return s;}
    Map<String,Object> policy(){Map<String,Object> p=new LinkedHashMap<>();p.put("enabled",1);p.put("owner_code","O1");p.put("allow_multi",1);p.put("allow_partial",1);p.put("allow_split_sku",0);p.put("warehouse_order",Arrays.asList("V1","V2"));p.put("province_priorities",Collections.singletonMap("北京市",Arrays.asList("V2")));return p;}
    @Test void provincePriorityThenDefaultOrderIsStableAndDeduplicated(){Map<String,Object> p=OrderAllocationPolicy.validate(policy(),Arrays.asList(store("V1","O1"),store("V2","O1")));assertEquals(Arrays.asList("V2","V1"),OrderAllocationPolicy.ordered(p,"北京"));assertEquals(Arrays.asList("V1","V2"),OrderAllocationPolicy.ordered(p,""));assertEquals("广西",OrderAllocationPolicy.province("广西壮族自治区"));assertEquals("新疆",OrderAllocationPolicy.province("新疆维吾尔自治区"));}
    @Test void otherOwnerAndNonAllowedPriorityWarehouseAreRejected(){assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(policy(),Arrays.asList(store("V1","O1"),store("V2","O2"))));Map<String,Object> p=policy();p.put("province_priorities",Collections.singletonMap("北京",Arrays.asList("V3")));assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(p,Arrays.asList(store("V1","O1"),store("V2","O1"))));}
    @Test void splitSkuNeedsMultiWarehouseAndEnabledNeedsAllowedStores(){Map<String,Object> p=policy();p.put("allow_multi",0);p.put("allow_split_sku",1);assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(p,Arrays.asList(store("V1","O1"),store("V2","O1"))));Map<String,Object> empty=policy();empty.put("warehouse_order",Collections.emptyList());assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(empty,Collections.emptyList()));}
    @Test void partialShippingGateDoesNotBypassReviewHoldOrPlatformBlock(){Map<String,Object> r=new HashMap<>();r.put("status","WAIT_ALLOCATION");r.put("review_status","APPROVED");r.put("platform_status","WAIT_SELLER_SEND_GOODS");r.put("inventory_status","PART_RESERVED");r.put("reserved_quantity",5);r.put("allocation_allow_partial",1);r.put("allocation_enabled",1);OrderReviewPolicy.decorate(r);assertEquals(true,r.get("can_allocate"));r.put("manual_hold",1);OrderReviewPolicy.decorate(r);assertEquals(false,r.get("can_allocate"));r.put("manual_hold",0);r.put("review_status","PENDING");OrderReviewPolicy.decorate(r);assertEquals(false,r.get("can_allocate"));r.put("review_status","APPROVED");r.put("change_pending",1);OrderReviewPolicy.decorate(r);assertEquals(false,r.get("can_allocate"));}
    @Test void fulfillmentStageAndWarehouseOccupationComeFromReceipts(){Map<String,Object> r=new HashMap<>();r.put("status","WAIT_ALLOCATION");r.put("review_status","APPROVED");r.put("allocation_status","PART");r.put("allocation_quantity",5);r.put("demand_quantity",10);assertEquals("PART_ALLOCATED",OrderReviewPolicy.businessStatus(r));OrderInventoryStatus.decorate(r);assertEquals("PART_OCCUPIED",r.get("warehouse_inventory_status"));r.put("allocation_status","FULL");r.put("allocation_quantity",10);assertEquals("WAIT_CARRIER",OrderReviewPolicy.businessStatus(r));r.put("shipment_quantity",10);r.put("pending_carrier_count",1);assertEquals("WAIT_CARRIER",OrderReviewPolicy.businessStatus(r));r.put("pending_carrier_count",0);assertEquals("WAIT_DISPATCH",OrderReviewPolicy.businessStatus(r));OrderInventoryStatus.decorate(r);assertEquals("OCCUPIED",r.get("warehouse_inventory_status"));r.put("status","VOIDED");OrderInventoryStatus.decorate(r);assertEquals("RELEASED",r.get("warehouse_inventory_status"));assertEquals(0L,r.get("warehouse_occupied_quantity"));}
    @Test void newPolicyFieldsDefaultWithoutChangingExistingWholeOrderPreference(){Map<String,Object> p=OrderAllocationPolicy.validate(policy(),Arrays.asList(store("V1","O1"),store("V2","O1")));assertEquals("FEWEST_SHIPMENTS",p.get("strategy"));assertEquals(0L,number(p,"max_shipments"));Map<String,Object> invalid=policy();invalid.put("strategy","UNKNOWN");assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(invalid,Arrays.asList(store("V1","O1"),store("V2","O1"))));invalid.put("strategy","REGION_FIRST");invalid.put("max_shipments",101);assertThrows(IllegalArgumentException.class,()->OrderAllocationPolicy.validate(invalid,Arrays.asList(store("V1","O1"),store("V2","O1"))));}
    long number(Map<String,Object> row,String key){return Long.parseLong(row.get(key).toString());}
}
